package com.bank.people;

import java.util.logging.Logger;

// Computes the diameter (longest path in edges) of the org tree.
public class DiameterService {

    private static final Logger log = Logger.getLogger(DiameterService.class.getName());

    private int maxDiameter;

    public int diameter(EmployeeNode root) {
        maxDiameter = 0;
        depth(root);
        return maxDiameter;
    }

    // Returns depth of subtree; also updates maxDiameter as a side effect.
    private int depth(EmployeeNode node) {
        if (node == null) {
            return 0;
        }
        int left = depth(node.getLeft());
        int right = depth(node.getRight());
        // Longest path THROUGH this node = left + right edges.
        maxDiameter = Math.max(maxDiameter, left + right);
        // This node's own depth for its parent.
        return 1 + Math.max(left, right);
    }

    public int longestRelationshipChain(EmployeeNode root) {
        int d = diameter(root);
        log.info(() -> "Longest relationship chain (edges) in org = " + d);
        return d;
    }
}
